#[derive(Debug, Clone, PartialEq, Default)]
pub struct ZzzzEntry {
    /// `ENAM`, optional.
    pub marker: Option<Empty>,
    /// `ENTR`, required.
    pub points: Option<ZzzzEntryPoints>,
}

impl ZzzzEntry {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"ENAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ENTR",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.marker,
                    subs,
                    *index,
                    "ZZZZ.Entry.ENAM",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.points,
                    subs,
                    *index,
                    "ZZZZ.Entry.ENTR",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"ENAM", self.marker.as_ref());
        emit(out, *b"ENTR", self.points.as_ref());
    }
}

