pub struct ZzzzTail {
    pub id: u32,
    pub rest: Bytes,
}

impl Field for ZzzzTail {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        Ok(Self {
            id: Field::read(r, "ZZZZ.TAIL.Id", ctx)?,
            rest: Field::read(r, "ZZZZ.TAIL.Rest", ctx)?,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.id.write(out);
        self.rest.write(out);
    }
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct ZzzzRecord {
    /// `EDID`, required.
    pub editor_id: Option<ZString>,
    /// `FULL`, optional.
    pub name: Option<LString>,
    /// `DATA`, required.
    pub data: Option<ZzzzData>,
    /// `VERS`, optional.
    pub versioned: Option<ZzzzVersioned>,
    /// `KWDA`, optional.
    pub keywords: Option<ZzzzKeywords>,
    /// Group `Entry`, repeated.
    pub entry: Vec<ZzzzEntry>,
    /// Group `Block`, repeated.
    pub block: Vec<ZzzzBlock>,
    /// `TAIL`, optional.
    pub tail: Option<ZzzzTail>,
    /// `BIG8`, optional.
    pub big_value: Option<i64>,
    /// `SKIP`, repeated.
    pub skipped: Vec<[u8; 2]>,
    /// Subrecords that matched no member or failed to decode, with their index in
    /// the record body.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl ZzzzRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"VERS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"KWDA",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: ZzzzEntry::MEMBERS,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: ZzzzBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"TAIL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"BIG8",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SKIP",
            card: Card::Repeated,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "ZZZZ.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.name, subs, *index, "ZZZZ.FULL", ctx, extra)
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.data, subs, *index, "ZZZZ.DATA", ctx, extra)
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.versioned, subs, *index, "ZZZZ.VERS", ctx, extra)
                }
                Hit::Sub { member: 4, index } => {
                    put(&mut self.keywords, subs, *index, "ZZZZ.KWDA", ctx, extra)
                }
                Hit::Group { member: 5, hits } => {
                    let mut group = ZzzzEntry::default();
                    group.fill(hits, subs, ctx, extra);
                    self.entry.push(group);
                }
                Hit::Group { member: 6, hits } => {
                    let mut group = ZzzzBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.block.push(group);
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.tail, subs, *index, "ZZZZ.TAIL", ctx, extra)
                }
                Hit::Sub { member: 8, index } => {
                    put(&mut self.big_value, subs, *index, "ZZZZ.BIG8", ctx, extra)
                }
                Hit::Sub { member: 9, index } => {
                    push(&mut self.skipped, subs, *index, "ZZZZ.SKIP", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"DATA", self.data.as_ref());
        emit(out, *b"VERS", self.versioned.as_ref());
        emit(out, *b"KWDA", self.keywords.as_ref());
        for group in &self.entry {
            group.emit(out);
        }
        for group in &self.block {
            group.emit(out);
        }
        emit(out, *b"TAIL", self.tail.as_ref());
        emit(out, *b"BIG8", self.big_value.as_ref());
        for value in &self.skipped {
            emit(out, *b"SKIP", Some(value));
        }
    }
}

impl ZzzzRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"ZZZZ";
    /// Record-header flag.
    pub const FLAG_ALPHA: u32 = 0x1;
    /// Record-header flag.
    pub const FLAG_BETA: u32 = 0x40000;

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at
    /// the indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }
}
